	// The old retired head is intentionally unreadable to the current reader.
	oldSubject := protocol.Control("gru", "host", "registration", "gru.gru-1-ctl-2")
	if _, err := js.Publish(t.Context(), oldSubject, []byte(`{"old_host_id":"sha256:obsolete"}`)); err != nil {
		t.Fatal(err)
	}
	mutations, err := authority.OpenReader(t.Context(), js, "gru")
	if err != nil {
		t.Fatal(err)
	}
	reader, err := host.NewReader(t.Context(), host.ReaderConfig{Cell: "gru", Conn: conn, JS: js, State: state, StateReplicas: 1, HostMutations: mutations, ControlLog: stream})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := reader.ListHosts(t.Context()); err == nil {
		t.Fatal("test did not establish obsolete retired registration failure")
	}
	for _, record := range plan.Records {
		if record.Action == HostStateAppendHead {
			if _, err := js.Publish(t.Context(), record.Pin.Key, record.Value); err != nil {
				t.Fatal(err)
			}
		}
	}
	statuses, err := reader.ListHosts(t.Context())
	if err != nil || len(statuses) != len(o.Hosts) {
		t.Fatalf("canonical host discovery = %d hosts, %v", len(statuses), err)
	}
	_, signer, _ := ed25519.GenerateKey(rand.Reader)
	controller, err := host.NewController(t.Context(), host.ControllerConfig{Cell: "gru", Conn: conn, JS: js, State: state,
		StateReplicas: 1, Artifacts: artifacts, HostMutations: mutations, ControlLog: stream, ResponseKey: signer,
		AuthorityEpoch: func() uint64 { return o.Epoch }, AuthorityGuard: func(context.Context, uint64) error { return nil }})
	if err != nil {
		t.Fatal(err)
	}
	for _, status := range statuses {
		if status.Registration.Generation != 12 {
			t.Fatal("registration did not advance beyond durable floor")
		}
		if _, err := controller.Register(t.Context(), status.Registration); err != nil {
			t.Fatalf("existing host registration validator: %v", err)
		}
		if status.Registration.Node == "gru-1-ctl-2" && !status.Retired {
			t.Fatal("inactive registration was reactivated")
		}
	}
	desired, err := reader.ListDesired(t.Context(), "terrabase")
	if err != nil || len(desired) != len(o.Hosts) {
		t.Fatalf("canonical desired discovery = %d targets, %v", len(desired), err)
	}
	for _, d := range desired {
		if d.Generation != 16 || d.AuthorityEpoch != o.Epoch {
			t.Fatal("desired did not advance beyond durable floors")
		}
		if _, err := controller.ApplyDesired(t.Context(), d); err != nil {
			t.Fatalf("existing host desired validator: %v", err)
		}
		for _, facts := range o.Hosts {
			if facts.Registration.Node != d.Node {
				continue
			}
			original := facts.Desired[0].Target
			d.Generation, d.AuthorityEpoch = original.Generation, original.AuthorityEpoch
			got, err := protocol.EncodeJSON(d)
			if err != nil {
				t.Fatal(err)
			}
			want, err := protocol.EncodeJSON(original)
			if err != nil || !bytes.Equal(got, want) {
				t.Fatal("handoff changed desired digest, execution environment or native identity")
			}
		}
	}
	grants, err := hostenroll.OpenGrantStore(t.Context(), js, 1)
	if err != nil {
		t.Fatal(err)
	}
	grantKV, err := js.KeyValue(t.Context(), hostenroll.GrantBucket)
	if err != nil {
		t.Fatal(err)
	}
	for _, record := range plan.Records {
		if record.Action != HostStateReplaceKV || record.Pin.Bucket != hostenroll.GrantBucket {
			continue
		}
		var grant hostenroll.Grant
		if err := protocol.DecodeStrict(record.Value, &grant, 64<<10); err != nil {
			t.Fatal(err)
		}
		if _, err := grantKV.Put(t.Context(), record.Pin.Key, record.Value); err != nil {
			t.Fatal(err)
		}
		if !entityid.Valid(grant.CreateKey) || len(grant.Response)+len(grant.RenewalResponse) != 0 {
			t.Fatal("fresh grant carries obsolete response or create key")
		}
		if grant.Disabled {
			if _, _, err := grants.ClaimRenew(t.Context(), grant.InstanceID, []byte("renewal request"), now); err == nil {
				t.Fatal("retired handoff grant admitted renewal")
			}
			continue
		}
		if grant.IdentityResetOperationID != o.OperationID {
			t.Fatal("active grant lost root reset provenance")
		}
		renewal := []byte("normal renewal after independently verified host request")
		claimed, revision, err := grants.ClaimRenew(t.Context(), grant.InstanceID, renewal, now)
		if err != nil {
			t.Fatalf("active host cannot renew after root handoff: %v", err)
		}
		if _, _, err := grants.ClaimRenew(t.Context(), grant.InstanceID, renewal, now); !errors.Is(err, hostenroll.ErrGrantInProgress) {
			t.Fatalf("handoff renewal is not serialized: %v", err)
		}
		response := []byte("fresh response signed by the replacement authority")
		if err := grants.FinishRenew(t.Context(), claimed, revision, response, now); err != nil {
			t.Fatal(err)
		}
		cached, _, err := grants.ClaimRenew(t.Context(), grant.InstanceID, renewal, now)
		if err != nil || !bytes.Equal(cached.RenewalResponse, response) {
			t.Fatalf("lost renewal reply cannot be recovered: %v", err)
		}
	}
}

func NewReader(ctx context.Context, cfg ReaderConfig) (*Reader, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.HostMutations == nil || cfg.Conn == nil {
		return nil, errors.New("reader requires NATS connection and ordered host mutation store")
	}
	state := cfg.State
	if state == nil {
		if cfg.JS == nil {
			return nil, errors.New("reader requires JetStream or host state")
		}
		var err error
		state, err = cfg.JS.KeyValue(ctx, stateBucket)
		if err != nil {
			return nil, err
		}
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	status, err := state.Status(ctx)
	if err != nil {
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		if cfg.JS == nil {
			return nil, errors.New("reader requires JetStream or control log")
		}
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, err
		}
	}
	return &Reader{controller: &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations, credentialFloor: cfg.ManagedCredentialFloor, readOnly: true}}, nil
}

func (r *Reader) ListHosts(ctx context.Context) ([]HostStatus, error) {
	return r.controller.ListHosts(ctx)
}

func (c *Controller) controlLogSubjects(ctx context.Context, filter string) (*jetstream.StreamInfo, error) {
	if err := c.lockControlLog(ctx); err != nil {
		return nil, err
	}
	defer func() { <-c.controlLogInfoGate }()
	return c.controlLog.Info(ctx, jetstream.WithSubjectFilter(filter))
}

func (c *Controller) lockControlLog(ctx context.Context) error {
	c.controlLogInfoOnce.Do(func() { c.controlLogInfoGate = make(chan struct{}, 1) })
	if err := ctx.Err(); err != nil {
		return err
	}
	select {
	case c.controlLogInfoGate <- struct{}{}:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (c *Controller) ListHosts(ctx context.Context) ([]HostStatus, error) {
	if c.controlLog == nil {
		return nil, errors.New("ordered control log is required for host discovery")
	}
	prefix := protocol.Control(c.cell, "host", "registration", c.cell) + "."
	info, err := c.controlLogSubjects(ctx, prefix+"*")
	if err != nil {
		return nil, err
	}
	var hosts []HostStatus
	for subject := range info.State.Subjects {
		node, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateToken(node, "node") != nil {
			return nil, errors.New("host registration subject is invalid")
		}
		r, registrationRevision, exists, err := c.readRegistration(ctx, node)
		if err != nil {
			return nil, err
		} else if !exists {
			continue
		}
		retirement, retirementRevision, err := c.readRetirement(ctx, node)
		if err != nil {
			return nil, err
		}
		status := HostStatus{Registration: r, Retired: retirement.Retired, Verified: !c.readOnly}
		s, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
		if err != nil {
			return nil, err
		}
		if exists && s.RegistrationGeneration == r.Generation && time.Now().Before(s.ExpiresAt) {
			status.SessionExpiresAt = s.ExpiresAt
			for _, role := range r.Roles {
				report, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil {
					return nil, err
				}
				if !ok || report.Cell != c.cell || report.Node != r.Node || report.Environment != r.Environment || report.Role != role ||
					report.SessionID != s.SessionID || report.Epoch != s.Epoch || time.Since(report.ObservedAt) >= ReportMaxAge || report.ObservedAt.After(time.Now().Add(maxClockSkew)) {
					continue
				}
				desired, desiredRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil {
					return nil, err
				}
				if !ok || report.Generation != desired.Generation || report.Digest != desired.Digest || desired.Withdrawn && report.State == "running" ||
					validateManagedReportForDesired(report, desired) != nil {
					continue
				}
				confirmed, confirmedRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil || !ok || confirmedRevision != desiredRevision || !sameJSON(confirmed, desired) {
					return nil, errors.New("desired changed during host status read")
				}
				check, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil || !ok || check.ObservedAt.Before(report.ObservedAt) || !sameReportMeaning(check, report) ||
					check.SessionID != s.SessionID || check.Epoch != s.Epoch || check.Generation != desired.Generation || check.Digest != desired.Digest ||
					validateManagedReportForDesired(check, desired) != nil ||
					time.Since(check.ObservedAt) >= ReportMaxAge || check.ObservedAt.After(time.Now().Add(maxClockSkew)) || desired.Withdrawn && check.State == "running" {
					return nil, errors.New("report changed during host status read")
				}
				status.Reports = append(status.Reports, check)
			}
			check, _, ok, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
			if err != nil || !ok || check.RegistrationGeneration != r.Generation || check.SessionID != s.SessionID || check.Epoch != s.Epoch || !time.Now().Before(check.ExpiresAt) {
				return nil, errors.New("session changed during host status read")
			}
			status.SessionExpiresAt = check.ExpiresAt
		}
		confirmed, confirmedRevision, ok, err := c.readRegistration(ctx, node)
		if err != nil || !ok || confirmedRevision != registrationRevision || !sameJSON(confirmed, r) {
			return nil, errors.New("registration changed during host status read")
		}
		if _, revision, err := c.readRetirement(ctx, node); err != nil || revision != retirementRevision {
			return nil, errors.New("retirement changed during host status read")
		}
		hosts = append(hosts, status)
	}
	slices.SortFunc(hosts, func(a, b HostStatus) int { return strings.Compare(a.Registration.Node, b.Registration.Node) })
	return hosts, nil
}

func (c *Controller) readRetirement(ctx context.Context, node string) (retirement, uint64, error) {
	if err := validateToken(node, "node"); err != nil {
		return retirement{}, 0, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRetirement, key)
	if errors.Is(err, authority.ErrNotFound) {
		return retirement{}, 0, nil
	}
	if err != nil {
		return retirement{}, 0, err
	}
	if entry.Kind != authority.MutationRetirement || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return retirement{}, 0, errors.New("retirement log entry is malformed")
	}
	mark, err := decodeRetirement(entry.Payload)
	if err != nil {
		return retirement{}, 0, err
	}
	return mark, entry.Sequence, nil
}

func decodeRetirement(payload []byte) (retirement, error) {
	var value struct {
		Retired *bool `json:"retired"`
	}
	if err := decodeStrict(payload, &value); err != nil {
		return retirement{}, err
	}
	if value.Retired == nil {
		return retirement{}, errors.New("retirement record requires a non-null retired state")
	}
	return retirement{Retired: *value.Retired}, nil
}

func (c *Controller) readRegistration(ctx context.Context, node string) (Registration, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Registration{}, 0, false, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRegistration, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Registration{}, 0, false, nil
	}
	if err != nil {
		return Registration{}, 0, false, err
	}
	if entry.Kind != authority.MutationRegistration || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Registration{}, 0, false, errors.New("registration log entry is malformed")
	}
	var r Registration
	if err := decodeStrict(entry.Payload, &r); err != nil {
		return Registration{}, 0, false, err
	}
	if r.Node != node || r.ID != entityid.Derive("host", c.cell, node) {
		return Registration{}, 0, false, errors.New("registration log identity mismatch")
	}
	if err := validateRegistration(r, c.cell); err != nil {
		return Registration{}, 0, false, err
	}
	return r, entry.Sequence, true, nil
}

func (c *Controller) readDesired(ctx context.Context, node, role string) (Desired, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Desired{}, 0, false, err
	}
	if err := validateToken(role, "role"); err != nil {
		return Desired{}, 0, false, err
	}
	key := desiredSubjectKey(c.cell, node, role)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationDesired, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Desired{}, 0, false, nil
	}
	if err != nil {
		return Desired{}, 0, false, err
	}
	if entry.Kind != authority.MutationDesired || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Desired{}, 0, false, errors.New("desired log entry is malformed")
	}
	var d Desired
	if err := decodeStrict(entry.Payload, &d); err != nil {
		return Desired{}, 0, false, err
	}
	if d.Cell != c.cell || d.Node != node || d.Role != role || d.AuthorityEpoch != entry.Epoch {
		return Desired{}, 0, false, errors.New("desired log identity or epoch mismatch")
	}
	return d, entry.Sequence, true, nil
}

func (c *Controller) ListDesired(ctx context.Context, role string) ([]Desired, error) {
	if c == nil || c.controlLog == nil || c.mutations == nil {
		return nil, errors.New("ordered host state reader is unavailable")
	}
	if role != "" {
		if err := validateToken(role, "role"); err != nil {
			return nil, err
		}
	}
	prefix := protocol.Control(c.cell, "host", "desired", c.cell) + "."
	filter := prefix + ">"
	if role != "" {
		filter = prefix + "*." + role
	}
	info, err := c.controlLogSubjects(ctx, filter)
	if err != nil {
		return nil, err
	}
	var result []Desired
	for subject := range info.State.Subjects {
		suffix, ok := strings.CutPrefix(subject, prefix)
		if !ok {
			return nil, errors.New("desired log subject has unexpected prefix")
		}
		node, roleName, ok := strings.Cut(suffix, ".")
		if !ok || validateToken(node, "node") != nil || validateToken(roleName, "role") != nil || strings.Contains(roleName, ".") {
			return nil, errors.New("desired log subject is malformed")
		}
		if role != "" && roleName != role {
			continue
		}
		d, revision, exists, err := c.readDesired(ctx, node, roleName)
		if err != nil {
			return nil, err
		}
		if !exists || revision == 0 {
			return nil, errors.New("desired log index is inconsistent")
		}
		result = append(result, d)
	}
	slices.SortFunc(result, func(a, b Desired) int {
		if a.Node < b.Node {
			return -1
		}
		if a.Node > b.Node {
			return 1
		}
		return strings.Compare(a.Role, b.Role)
	})
	return result, nil
}

func (r *Reader) ListDesired(ctx context.Context, role string) ([]Desired, error) {
	return r.controller.ListDesired(ctx, role)
}

func OpenReader(ctx context.Context, js jetstream.JetStream, scope string) (*Reader, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	if !natsToken.MatchString(scope) {
		return nil, errors.New("authority scope must be a canonical ULID")
	}
	stream, err := js.Stream(ctx, ControlStreamName)
	if err != nil {
		return nil, err
	}
	info, err := stream.Info(ctx)
	if err != nil {
		return nil, err
	}
	if err := verifyControlStreamConfig(info.Config, info.Config.Replicas); err != nil {
		return nil, err
	}
	return &Reader{stream: stream, scope: scope}, nil
}

func (r *Reader) CommitHostMutation(context.Context, uint64, HostMutationKind, string, string, uint64, []byte) (uint64, error) {
	return 0, ErrNotLeader
}

func (r *Reader) CommitHostMutationVerified(context.Context, uint64, HostMutationKind, string, string, uint64, []byte, func(context.Context) error) (uint64, error) {
	return 0, ErrNotLeader
}

func (r *Reader) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil || r.stream == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	return readMutation(ctx, r.stream, r.scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

func (c *Controller) Register(ctx context.Context, r Registration) (Receipt, error) {
	id := entityid.Derive("host", r.Cell, r.Node)
	if r.ID != "" && r.ID != id {
		return Receipt{}, errors.New("host ID differs from its node identity")
	}
	r.ID = id
	if err := validateRegistration(r, c.cell); err != nil {
		return Receipt{}, err
	}
	if r.ManagedOCI != nil && r.ManagedPlacement == nil {
		return Receipt{}, errors.New("managed host registration requires current schema-3 placement pins")
	}
	authorityEpoch := c.authorityEpoch()
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return Receipt{}, err
	}
	if r.ManagedMember != nil {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil {
			return Receipt{}, errors.New("managed host registration requires a terminal effect gate and placement scope")
		}
		release, err := c.managedEffectGate(ctx, authorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	c.registrationMu.Lock()
	defer c.registrationMu.Unlock()
	payload, operationID, err := mutationPayload(r)
	if err != nil {
		return Receipt{}, err
	}
	key := registrationSubjectKey(c.cell, r.Node)
	for range 8 {
		if r.ManagedMember != nil {
			if c.managedVerifier == nil {
				return Receipt{}, errors.New("managed host registration requires a current placement verifier")
			}
			if err := c.managedVerifier.VerifyManagedRegistration(ctx, r); err != nil {
				return Receipt{}, fmt.Errorf("verify managed host registration: %w", err)
			}
			if err := c.requireExclusiveManagedMember(ctx, r); err != nil {
				return Receipt{}, err
			}
		}
		current, revision, exists, err := c.readRegistration(ctx, r.Node)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedOCI == nil) != (r.ManagedOCI == nil) ||
				current.ManagedOCI != nil && (current.ManagedMember == nil || *current.ManagedOCI != *r.ManagedOCI ||
					*current.ManagedMember != *r.ManagedMember || current.FailureDomain != r.FailureDomain) {
				return Receipt{}, errors.New("host managed binding cannot be retargeted")
			}
			if r.Generation < current.Generation {
				return Receipt{}, errors.New("registration generation moved backward")
			}
			if r.Generation == current.Generation {
				if !sameJSON(r, current) {
					return Receipt{}, errors.New("registration changed without a generation increase")
				}
				return Receipt{r.Generation, revision}, nil
			}
		}
		if err := c.guard(ctx, authorityEpoch); err != nil {
			return Receipt{}, err
		}
		written, err := c.mutations.CommitHostMutation(ctx, authorityEpoch, authority.MutationRegistration, key, operationID, revision, payload)
		if err == nil {
			return Receipt{r.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("registration contention")
}

func (c *Controller) ApplyDesired(ctx context.Context, d Desired) (Receipt, error) {
	if err := c.guard(ctx, d.AuthorityEpoch); err != nil {
		return Receipt{}, err
	}
	c.retireMu.RLock()
	defer c.retireMu.RUnlock()
	if !d.Withdrawn {
		retired, err := c.retired(ctx, d.Node)
		if err != nil {
			return Receipt{}, err
		}
		if retired {
			return Receipt{}, fmt.Errorf("%w: %s", ErrHostRetiring, d.Node)
		}
	}
	r, _, exists, err := c.readRegistration(ctx, d.Node)
	if err != nil {
		return Receipt{}, err
	}
	if !exists {
		return Receipt{}, errors.New("host is not registered")
	}
	if err := validateDesired(d, c.cell, r); err != nil {
		return Receipt{}, err
	}
	if d.ManagedMember != nil && !d.Withdrawn {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil || c.managedDesiredVerifier == nil {
			return Receipt{}, errors.New("managed desired requires a terminal effect gate, placement scope and durable verifier")
		}
		release, err := c.managedEffectGate(ctx, d.AuthorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	bucket := ""
	if !d.Withdrawn {
		info, err := c.artifacts.GetInfo(ctx, "sha256-"+d.Digest)
		if err != nil {
			return Receipt{}, err
		}
		if info.Deleted || info.Opts != nil && info.Opts.Link != nil || info.Size == 0 || info.Size > maxArtifactBytes {
			return Receipt{}, errors.New("artifact is absent, linked or outside size limit")
		}
		bucket = info.Bucket
	}
	payload, operationID, err := mutationPayload(d)
	if err != nil {
		return Receipt{}, err
	}
	key := desiredSubjectKey(c.cell, d.Node, d.Role)
	for range 8 {
		currentRegistration, _, registered, err := c.readRegistration(ctx, d.Node)
		if err != nil {
			return Receipt{}, err
		}
		if !registered || validateDesired(d, c.cell, currentRegistration) != nil {
			return Receipt{}, errors.New("registration changed before desired commit")
		}
		current, revision, exists, err := c.readDesired(ctx, d.Node, d.Role)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedMember == nil) != (d.ManagedMember == nil) {
				return Receipt{}, fmt.Errorf("%w: managed desired kind changed", ErrDesiredConflict)
			}
			if current.ManagedMember != nil && d.ManagedMember != nil &&
				(current.ManagedMember.Member != d.ManagedMember.Member || current.ManagedMember.OCI != d.ManagedMember.OCI ||
					current.ManagedMember.VolumeID != d.ManagedMember.VolumeID || current.ManagedMember.AttachmentID != d.ManagedMember.AttachmentID) {
				return Receipt{}, fmt.Errorf("%w: managed member or attachment retargeted", ErrDesiredConflict)
			}
			if d.AuthorityEpoch < current.AuthorityEpoch || d.Generation < current.Generation {
				return Receipt{}, fmt.Errorf("%w: generation or epoch moved backward", ErrDesiredConflict)
			}
			if d.Generation == current.Generation {
				if !sameDesiredTarget(d, current) {
					return Receipt{}, fmt.Errorf("%w: target changed within a generation", ErrDesiredConflict)
				}
				if d.AuthorityEpoch == current.AuthorityEpoch {
					return Receipt{d.Generation, revision}, nil
				}
			}
		}
		// The artifact collector deletes only metadata nobody touched since
		// it chose the artifact, so it cannot delete the bytes this desired
		// is about to name.
		if bucket != "" && c.conn != nil {
			js, err := c.conn.JetStream()
			if err != nil {
				return Receipt{}, err
			}
			if err := artifact.Touch(ctx, js, bucket, "sha256-"+d.Digest); err != nil {
				return Receipt{}, fmt.Errorf("pin desired artifact: %w", err)
			}
		}
		if err := c.guard(ctx, d.AuthorityEpoch); err != nil {
			return Receipt{}, err
		}
		var written uint64
		if d.ManagedMember != nil && !d.Withdrawn {
			verified, ok := c.mutations.(authority.VerifiedHostMutationStore)
			if !ok {
				return Receipt{}, errors.New("managed desired mutation store lacks a final verifier fence")
			}
			verify := func(verifyCtx context.Context) error {
				return c.managedDesiredVerifier(verifyCtx, d, currentRegistration, current, exists)
			}
			written, err = verified.CommitHostMutationVerified(ctx, d.AuthorityEpoch, authority.MutationDesired,
				key, operationID, revision, payload, verify)
		} else {
			written, err = c.mutations.CommitHostMutation(ctx, d.AuthorityEpoch, authority.MutationDesired,
				key, operationID, revision, payload)
		}
		if err == nil {
			return Receipt{d.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("desired contention")
}

func OpenGrantStore(ctx context.Context, js jetstream.JetStream, replicas int) (*GrantStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("host enrollment requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: GrantBucket, History: 2, MaxValueSize: MaxGrantBytes,
		MaxBytes: 64 << 20, Storage: jetstream.FileStorage, Replicas: replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open host enrollment grants: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil || status.Config().Replicas != replicas {
		return nil, errors.New("host enrollment grant replication differs from regional quorum")
	}
	return &GrantStore{kv: kv, js: js}, nil
}

func grantKey(instanceID string) string {
	return entityid.Derive("host-enrollment", instanceID)
}

func (store *GrantStore) Read(ctx context.Context, instanceID string) (Grant, uint64, error) {
	if store == nil || store.kv == nil || instanceID == "" {
		return Grant{}, 0, errors.New("host enrollment grant store is unavailable")
	}
	entry, err := store.kv.Get(ctx, grantKey(instanceID))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &grant, json.RejectUnknownMembers(true)) != nil || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("host enrollment grant is corrupt")
	}
	return grant, entry.Revision(), nil
}

func (store *GrantStore) ClaimRenew(ctx context.Context, instanceID string, request []byte,
	now time.Time,
) (Grant, uint64, error) {
	if len(request) == 0 || len(request) > 16<<10 {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal request is invalid"))
	}
	grant, revision, err := store.Read(ctx, instanceID)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	// Root reset provenance permits completing a grant without replaying an old response.
	resetPending := len(grant.Response) == 0 && entityid.Valid(grant.IdentityResetOperationID) &&
		grant.SchemaVersion == 1 && entityid.Valid(grant.CreateKey) && len(grant.DescriptorSHA256) == 64 &&
		len(grant.Request) != 0 && len(grant.Request) <= MaxRequestBytes && grant.OwnerToken == "" && grant.LeaseUntil.IsZero() && grant.TerminalOperationID == ""
	if grant.Disabled || len(grant.Response) == 0 && !resetPending {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant is disabled or incomplete"))
	}
	if bytes.Equal(grant.RenewalRequest, request) && len(grant.RenewalResponse) != 0 {
		return grant, revision, nil
	}
	if len(grant.RenewalRequest) != 0 && len(grant.RenewalResponse) == 0 && now.Before(grant.RenewalLeaseUntil) {
		return Grant{}, 0, mutationNotApplied(ErrGrantInProgress)
	}
	var previous Response
	if len(grant.RenewalResponse) != 0 {
		if json.Unmarshal(grant.RenewalResponse, &previous, json.RejectUnknownMembers(true)) != nil ||
			now.Before(previous.ExpiresAt.Add(-24*time.Hour)) {
			return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal is not due"))
		}
	} else if len(grant.RenewalRequest) == 0 && !resetPending {
		if json.Unmarshal(grant.Response, &previous, json.RejectUnknownMembers(true)) != nil ||
			now.Before(previous.ExpiresAt.Add(-24*time.Hour)) {
			return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal is not due"))
		}
	}
	token := make([]byte, 32)
	if _, err := rand.Read(token); err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	grant.RenewalRequest = bytes.Clone(request)
	grant.RenewalResponse = nil
	grant.RenewalToken = base64.RawURLEncoding.EncodeToString(token)
	grant.RenewalLeaseUntil = now.Add(time.Minute)
	wire, err := json.Marshal(grant)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	next, err := store.kv.Update(ctx, grantKey(instanceID), wire, revision)
	if err != nil {
		wrapped := fmt.Errorf("claim host enrollment renewal: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, 0, mutationNotApplied(wrapped)
		}
		return Grant{}, 0, wrapped
	}
	return grant, next, nil
}

func (store *GrantStore) FinishRenew(ctx context.Context, expected Grant, revision uint64,
	response []byte, now time.Time,
) error {
	if store == nil || store.kv == nil || revision == 0 || expected.Disabled ||
		expected.RenewalToken == "" || !now.Before(expected.RenewalLeaseUntil) ||
		len(expected.RenewalRequest) == 0 || len(expected.RenewalResponse) != 0 ||
		len(response) == 0 || len(response) > 32<<10 {
		return mutationNotApplied(errors.New("host enrollment renewal cannot be committed"))
	}
	expected.RenewalResponse = bytes.Clone(response)
	wire, err := json.Marshal(expected)
	if err != nil {
		return mutationNotApplied(err)
	}
	_, err = store.kv.Update(ctx, grantKey(expected.InstanceID), wire, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return mutationNotApplied(err)
	}
	return err
}

func GuestBuild(ctx context.Context, repo string, o GuestBuildOptions, out io.Writer) (result error) {
	pin, e := client.LoadPin(filepath.Join(repo, "deploy/image/image-inputs.json"))
	if e != nil {
		return e
	}
	architecture, e := binaryArchitecture(o.Binary)
	if e != nil {
		return e
	}
	nativeArchitecture, e := binaryArchitecture(o.NativeVerifier)
	if e != nil {
		return e
	}
	if nativeArchitecture != architecture {
		return errors.New("native verifier and orchestrator architectures differ")
	}
	archive, e := pin.Archive(architecture)
	if e != nil {
		return e
	}
	if e = client.VerifyBinary(o.NetBirdBinary, archive.BinarySHA256, architecture); e != nil {
		return e
	}
	g, e := NewGuest(ctx, o.Image, false, nil)
	if e != nil {
		return e
	}
	defer func() { result = errors.Join(result, g.Close(result != nil)) }()

func OfflineBuild(ctx context.Context, repo string, o OfflineOptions, out io.Writer) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	for _, required := range []string{o.Base, o.KernelRelease, o.Binary, o.Qualification, o.SourceRevision, o.NativeVerifier, o.NativeSHA256, o.ReleaseTool, o.Timesyncd, o.Out, o.KernelOut} {
		if required == "" {
			return errors.New("missing required build-offline argument")
		}
	}
	if len(o.BootstrapRoots) == 0 || len(o.BootstrapRoots) > bootstrapstart.MaxRootFiles {
		return fmt.Errorf("bootstrap root set must contain at most %d files", bootstrapstart.MaxRootFiles)
	}
	if !gitSHA.MatchString(o.SourceRevision) {
		return errors.New("source revision must be a full lowercase Git SHA-1")
	}
	if !kernelRelease.MatchString(o.KernelRelease) {
		return errors.New("kernel release must be a plain Linux release string")
	}
	if !client.SHA256Pattern.MatchString(o.NativeSHA256) {
		return errors.New("native verifier SHA-256 must be 64 lowercase hex characters")
	}
	if (o.NetBirdBinary != "" || o.NetBirdSHA256 != "") && (o.NetBirdBinary == "" || !client.SHA256Pattern.MatchString(o.NetBirdSHA256)) {
		return errors.New("a supplied NetBird binary needs --netbird-binary and a lowercase --netbird-sha256")
	}
	pin, e := client.LoadPin(filepath.Join(repo, "deploy/image/image-inputs.json"))
	if e != nil {
		return e
	}
	architecture, e := binaryArchitecture(o.Binary)
	if e != nil {
		return e
	}
	archive, e := pin.Archive(architecture)
	if e != nil {
		return e
	}
	if o.NetBirdBinary != "" && o.NetBirdSHA256 != archive.BinarySHA256 {
		return errors.New("supplied NetBird SHA-256 differs from the image pin")
	}
	for _, tool := range []string{"qemu-img", "guestfish", "systemctl", "systemd-sysusers"} {
		if _, e := exec.LookPath(tool); e != nil {
			return fmt.Errorf("missing required command: %s", tool)
		}

func binaryArchitecture(name string) (string, error) {
	f, err := elf.Open(name)
	if err != nil {
		return "", err
	}
	defer f.Close()
	if f.Class != elf.ELFCLASS64 || f.Data != elf.ELFDATA2LSB || (f.Type != elf.ET_EXEC && f.Type != elf.ET_DYN) {
		return "", errors.New("host binary must be a little-endian ELF64 executable")
	}
	switch f.Machine {
	case elf.EM_AARCH64:
		return "arm64", nil
	case elf.EM_X86_64:
		return "amd64", nil
	}
	return "", errors.New("host binary must target Linux arm64 or amd64")
}

func LoadPin(path string) (Pin, error) {
	var inputs map[string]jsontext.Value
	b, err := os.ReadFile(path)
	if err != nil {
		return Pin{}, err
	}
	if err = json.Unmarshal(b, &inputs); err != nil {
		return Pin{}, err
	}
	raw, ok := inputs["netbird"]
	if !ok {
		return Pin{}, errors.New("missing NetBird input pin")
	}
	return ValidatePinJSON(raw)
}

func BuildReleaseTool(ctx context.Context, root, work, source, prebuilt string, run Exec) (tool string, prefix []string, record map[string]any, result error) {
	prefix = []string{"release"}
	if run == nil {
		run = Execute
	}
	if prebuilt != "" {
		tool, result = filepath.Abs(prebuilt)
		if result != nil {
			return
		}
	} else {
		if !gitSHA.MatchString(source) {
			result = errors.New("invalid image source revision")
			return
		}
		// go build runs inside the source worktree: a relative -o would
		// land in (and be removed with) that worktree.
		if work, result = filepath.Abs(work); result != nil {
			return
		}
		checkout := filepath.Join(work, "source")
		if _, result = run(ctx, "", nil, "git", "-C", root, "fetch", "--quiet", "origin", "main"); result != nil {
			return
		}
		if _, result = run(ctx, "", nil, "git", "-C", root, "worktree", "add", "--quiet", "--detach", checkout, source); result != nil {
			return
		}
		func() {
			defer func() {
				cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), time.Minute)
				defer cancel()
				_, cleanupErr := run(cleanupCtx, "", nil, "git", "-C", root, "worktree", "remove", "--force", checkout)
				result = errors.Join(result, cleanupErr)
			}()
			target := "./cmd/ts-release"
			name := "ts-release"
			prefix = []string{}
			if s, e := os.Stat(filepath.Join(checkout, "internal/release/cli/run.go")); e == nil && s.Mode().IsRegular() {
				target = "./cmd/terrascale-orchestrator"
				name = "ts-orch"
				prefix = []string{"release"}
			}
			tool = filepath.Join(work, name)
			_, result = run(ctx, checkout, nil, "nice", "-n", "19", "go", "build", "-trimpath", "-buildvcs=true", "-o", tool, target)
		}()
		if result != nil {
			return
		}
		var metadata string
		metadata, result = run(ctx, "", nil, "go", "version", "-m", tool)
		if result != nil {
			return
		}
		if !strings.Contains(metadata, "vcs.revision="+source) || !strings.Contains(metadata, "vcs.modified=false") {
			result = errors.New("release tool was not built from the clean image source revision")
			return
		}
	}
	s, e := os.Stat(tool)
	if e != nil || !s.Mode().IsRegular() || s.Mode().Perm()&0111 == 0 {
		result = fmt.Errorf("release tool is not executable: %s", tool)
		return
	}
	digest, e := fileHash(tool)
	if e != nil {
		result = e
		return
	}
	record = map[string]any{"path": tool, "sha256": digest}
	return
}

func writeCheckpoint(path string, b []byte) error {
	if existing, e := os.ReadFile(path); e == nil && string(existing) == string(b) {
		return nil
	}
	temporary, e := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-")
	if e != nil {
		return e
	}
	defer os.Remove(temporary.Name())
	if _, e = temporary.Write(b); e == nil {
		e = temporary.Sync()
	}
	if e == nil {
		e = temporary.Chmod(0644)
	}
	if closeErr := temporary.Close(); e == nil {
		e = closeErr
	}
	if e != nil {
		return e
	}
	if e = os.Rename(temporary.Name(), path); e != nil {
		return e
	}
	dir, e := os.Open(filepath.Dir(path))
	if e != nil {
		return e
	}
	defer dir.Close()
	return dir.Sync()
}

func (p *promotion) freshOutput(path string) error {
	s, e := os.Lstat(path)
	if os.IsNotExist(e) {
		return nil
	}
	if e != nil {
		return e
	}
	if !p.o.Resume || !s.Mode().IsRegular() {
		return fmt.Errorf("promotion output already exists: %s", path)
	}
	aside := fmt.Sprintf("%s.superseded-%d", path, time.Now().UnixNano())
	p.step("regenerating " + filepath.Base(path) + "; the earlier one is kept as " + filepath.Base(aside))
	return os.Rename(path, aside)
}

func reuseReleaseTool(ctx context.Context, dir, source string, run Exec) (string, []string, map[string]any, bool) {
	if run == nil {
		run = Execute
	}
	var recorded struct {
		Schema         string   `json:"schema"`
		Path           string   `json:"path"`
		SHA256         string   `json:"sha256"`
		SourceRevision string   `json:"source_revision"`
		Prefix         []string `json:"prefix"`
	}
	if readJSON(filepath.Join(dir, releaseToolRecord), &recorded) != nil || recorded.Schema != releaseToolRecordV1 ||
		recorded.SourceRevision != source || filepath.Dir(filepath.Dir(recorded.Path)) != dir ||
		!strings.HasPrefix(filepath.Base(filepath.Dir(recorded.Path)), "build-") {
		return "", nil, nil, false
	}
	digest, e := fileHash(recorded.Path)
	if e != nil || digest != recorded.SHA256 {
		return "", nil, nil, false
	}
	metadata, e := run(ctx, "", nil, "go", "version", "-m", recorded.Path)
	if e != nil || !strings.Contains(metadata, "vcs.revision="+source) || !strings.Contains(metadata, "vcs.modified=false") {
		return "", nil, nil, false
	}
	return recorded.Path, recorded.Prefix, map[string]any{"path": recorded.Path, "sha256": digest, "reused": true}, true
}

func recordReleaseTool(dir, source string, prefix []string, record map[string]any) error {
	b, e := canonical(map[string]any{"schema": releaseToolRecordV1, "path": record["path"], "sha256": record["sha256"],
		"source_revision": source, "prefix": prefix})
	if e != nil {
		return e
	}
	return os.WriteFile(filepath.Join(dir, releaseToolRecord), b, 0644)
}

func SHA256(path string) (string, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", e
	}
	defer f.Close()
	h := sha256.New()
	if _, e = io.Copy(h, f); e != nil {
		return "", e
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func (p *promotion) step(message string) { fmt.Fprintln(p.out, "promote-image:", message) }
func (p *promotion) run(capture bool, command ...string) (string, error) {
	out, e := Execute(p.ctx, "", nil, command...)
	if e != nil {
		action := ""
		if len(command) > 1 {
			action = command[1]
		}
		if (action == "release" || action == "bootstrap") && len(command) > 2 {
			action += " " + command[2]
		}
		return "", fmt.Errorf("%s %s failed: %w", filepath.Base(command[0]), action, e)
	}
	if !capture && out != "" {
		fmt.Fprintln(p.out, out)
	}
	return out, nil

// fetch downloads asset unless a resumed promotion already holds a file
// whose SHA-256 equals the expected pinned digest. Every caller still
// verifies the digest of whatever file it ends up using.
func (p *promotion) fetch(tag, asset, destination, expected string) (string, error) {
	if p.o.Resume && expected != "" {
		if digest, e := fileHash(destination); e == nil && digest == expected {
			p.step("reusing verified " + asset)
			return destination, nil
		}
	}
	return p.download(tag, asset, destination)
}
func (p *promotion) download(tag, asset, destination string) (string, error) {
	if e := os.MkdirAll(filepath.Dir(destination), 0755); e != nil {
		return "", e
	}
	_, e := p.run(true, "gh", "release", "download", tag, "--repo", repository, "--pattern", asset, "--output", destination, "--clobber")
	return destination, e
}
func (p *promotion) acquireImage() error {
	imageDir := filepath.Join(p.o.Out, "image")
	if p.o.ImageRelease != "" {
		if !regexp.MustCompile(`^image-[0-9a-f]{40}-run-[1-9][0-9]*-attempt-[1-9][0-9]*$`).MatchString(p.o.ImageRelease) {
			return fmt.Errorf("not an image release tag: %s", p.o.ImageRelease)
		}
		// SHA256SUMS is small and always fresh; it pins the large assets a
		// resumed promotion may reuse.
		if _, e := p.download(p.o.ImageRelease, imageAssets[3], filepath.Join(imageDir, imageAssets[3])); e != nil {
			return e
		}
		pinned, e := readImageSums(filepath.Join(imageDir, imageAssets[3]))
		if e != nil {
			return e
		}
		for _, asset := range imageAssets[:3] {
			if _, e := p.fetch(p.o.ImageRelease, asset, filepath.Join(imageDir, asset), pinned[asset]); e != nil {
				return e
			}
		}
	} else {
		mkdir := os.Mkdir
		if p.o.Resume {
			mkdir = os.MkdirAll
		}
		if e := mkdir(imageDir, 0755); e != nil {
			return e
		}
		for _, asset := range imageAssets {
			src := filepath.Join(p.o.ImageDir, asset)
			if s, e := os.Stat(src); e != nil || !s.Mode().IsRegular() {
				return fmt.Errorf("local image directory lacks %s", asset)
			}
			if e := copyFile(src, filepath.Join(imageDir, asset), 0644); e != nil {
				return e
			}
		}
	}
	sums, e := readImageSums(filepath.Join(imageDir, "SHA256SUMS"))
	if e != nil {
		return e
	}
	for _, asset := range imageAssets[:3] {
		digest := sums[asset]
		observed, e := fileHash(filepath.Join(imageDir, asset))
		if e != nil {
			return e
		}
		if observed != digest {
			return fmt.Errorf("image asset differs from SHA256SUMS: %s", asset)
		}
	}
	manifestPath := filepath.Join(imageDir, "image-qualification.json")
	if e = readJSON(manifestPath, &p.manifest); e != nil {
		return e
	}
	if e = readJSON(manifestPath, &p.raw); e != nil {
		return e
	}
	m := p.manifest
	if m.Schema != "terrascale.image.qualification.v2" {
		return errors.New("unsupported image manifest schema")
	}
	if m.Image.SHA256 != sums[imageAssets[0]] || m.Kernel.SHA256 != sums[imageAssets[1]] {
		return errors.New("image manifest digests differ from SHA256SUMS")
	}
	if !gitSHA.MatchString(m.SourceRevision) || !gitSHA.MatchString(m.SourceTree) {
		return errors.New("image manifest source must be a full lowercase Git SHA")
	}
	provenance := map[string]any{"manifest_sha256": sums[imageAssets[2]], "builder": p.raw["builder"]}

	} else {
		source, e := filepath.Abs(p.o.ImageDir)
		if e != nil {
			return e
		}
		provenance["image_dir"] = source
		p.step(fmt.Sprintf("local image verified builder=%s source=%s", m.Builder.Kind, m.SourceRevision))
	}
	rawImage, ok := p.raw["image"].(map[string]any)
	if !ok {
		return errors.New("invalid image metadata")
	}
	imageRecord := map[string]any{}
	for k, v := range rawImage {
		imageRecord[k] = v
	}
	imageRecord["kernel"] = p.raw["kernel"]
	imageRecord["source_revision"] = m.SourceRevision
	imageRecord["source_tree"] = m.SourceTree
	imageRecord["provenance"] = provenance
	p.receipt["image"] = imageRecord
	return nil
}

// readImageSums parses SHA256SUMS, which must list exactly the image,
// kernel and manifest.
func readImageSums(path string) (map[string]string, error) {
	invalid := errors.New("SHA256SUMS must list exactly the image, kernel and manifest")
	b, e := os.ReadFile(path)
	if e != nil {
		return nil, e
	}
	sums := map[string]string{}
	for line := range strings.SplitSeq(strings.TrimSuffix(string(b), "\n"), "\n") {
		digest, name, ok := strings.Cut(line, "  ")
		if !ok || !regexp.MustCompile(`^[0-9a-f]{64}$`).MatchString(digest) {
			return nil, invalid
		}
		if _, exists := sums[name]; exists {
			return nil, invalid
		}
		sums[name] = digest
	}
	if len(sums) != 3 {
		return nil, invalid
	}
	for _, asset := range imageAssets[:3] {
		if _, ok := sums[asset]; !ok {
			return nil, invalid
		}
	}
	return sums, nil
}

// checkResumeState refuses to resume an --out directory that belongs to a
// different image release, directory or image digest, then records the pin.
func (p *promotion) checkResumeState(imageSHA256 string) error {
	path := filepath.Join(p.o.Out, promotionStateFile)
	want := promotionState{Schema: promotionStateV1, ImageRelease: p.o.ImageRelease, ImageSHA256: imageSHA256}
	if p.o.ImageDir != "" {
		source, e := filepath.Abs(p.o.ImageDir)
		if e != nil {
			return e
		}
		want.ImageDir = source
	}
	var existing promotionState
	if e := readJSON(path, &existing); e == nil {
		if existing.Schema != promotionStateV1 || existing.ImageRelease != want.ImageRelease || existing.ImageDir != want.ImageDir ||
			imageSHA256 != "" && existing.ImageSHA256 != "" && existing.ImageSHA256 != imageSHA256 {
			return fmt.Errorf("--out %s belongs to a different promotion; use a new directory", p.o.Out)
		}
		if imageSHA256 == "" {
			return nil
		}
	} else if !os.IsNotExist(e) {
		return e
	}
	b, e := canonical(want)
	if e != nil {
		return e
	}
	return writeCheckpoint(path, b)

func (p *promotion) acquireCandidate() (candidateFiles, error) {
	var files candidateFiles
	c := p.manifest.Candidate
	dir := filepath.Join(p.o.Out, "candidate")
	var e error
	if files.qualification, e = p.fetch(c.Tag, "qualification.json", filepath.Join(dir, "qualification.json"), c.QualificationSHA256); e != nil {
		return files, e
	}
	if files.binary, e = p.fetch(c.Tag, orchestratorAsset, filepath.Join(dir, orchestratorAsset), c.BinarySHA256); e != nil {
		return files, e
	}
	qd, e := fileHash(files.qualification)
	if e != nil {
		return files, e
	}
	bd, e := fileHash(files.binary)
	if e != nil {
		return files, e
	}
	if qd != c.QualificationSHA256 || bd != c.BinarySHA256 {
		return files, fmt.Errorf("candidate release %s differs from the image manifest", c.Tag)
	}
	files.receipt = filepath.Join(dir, "binary.receipt.json")
	if p.o.BinaryReceipt != "" {
		if e = copyFile(p.o.BinaryReceipt, files.receipt, 0644); e != nil {
			return files, e
		}
	} else {
		if _, e = p.download(c.Tag, p.o.Environment+"-linux-arm64.receipt.json", files.receipt); e != nil {
			os.Remove(files.receipt)
			files.receipt = ""
			// A resumed promotion reuses the receipt it signed earlier;
			// verify-binary still checks it against the exact binary.
			signed := filepath.Join(p.o.Out, "binary.receipt.json")
			if s, statErr := os.Stat(signed); p.o.Resume && statErr == nil && s.Mode().IsRegular() {
				files.receipt = signed
				p.step("reusing signed binary receipt")
			}
		}
	}
	base := p.manifest.Inputs.Manifest.Base
	if files.base, e = p.fetch(base.ReleaseTag, "base-image.qcow2", filepath.Join(p.o.Out, "base-image.qcow2"), base.Assets.Base.SHA256); e != nil {
		return files, e
	}
	digest, e := fileHash(files.base)
	if e != nil {
		return files, e
	}
	if digest != base.Assets.Base.SHA256 {
		return files, errors.New("base QCOW2 differs from the image inputs pin")
	}
	p.receipt["candidate"] = p.raw["go_candidate"]
	p.receipt["base"] = map[string]any{"release_tag": base.ReleaseTag, "oci_image_ocid": base.OCIImageOCID, "sha256": base.Assets.Base.SHA256}
	p.step(fmt.Sprintf("candidate verified tag=%s binary_sha256=%s", c.Tag, c.BinarySHA256))
	return files, nil
}

func Promote(ctx context.Context, root string, o PromotionOptions, out io.Writer) error {
	// The release tool is built with its working directory in a source
	// worktree, so every path derived from --out must be absolute.
	absoluteOut, e := filepath.Abs(o.Out)
	if e != nil {
		return e
	}
	o.Out = absoluteOut
	p := &promotion{ctx: ctx, root: root, o: o, out: out}
	gh, e := exec.LookPath("gh")
	if e != nil {
		return errors.New("gh is required on PATH")
	}
	digest, e := fileHash(gh)
	if e != nil {
		return e
	}
	tools := map[string]any{"gh": map[string]any{"path": gh, "sha256": digest}}
	p.receipt = map[string]any{"schema": "terrascale.image.promotion.v1", "dry_run": o.DryRun, "started_at": time.Now().UTC().Format(time.RFC3339), "environment": o.Environment, "tools": tools}
	if o.Resume {
		p.receipt["resumed"] = true
		if e = os.MkdirAll(o.Out, 0755); e != nil {
			return e
		}
		if e = p.checkResumeState(""); e != nil {
			return e
		}
	} else if e = os.Mkdir(o.Out, 0755); e != nil {
		return e
	}
	virtCat, e := exec.LookPath("virt-cat")
	if e != nil {
		return errors.New("virt-cat is required; run under deploy/image/tools.sh")
	}
	version, e := p.run(true, virtCat, "--version")
	if e != nil {
		return e
	}
	tools["virt_cat"] = map[string]any{"path": virtCat, "version": version}
	if e = p.acquireImage(); e != nil {
		return e
	}
	if e = p.checkResumeState(p.manifest.Image.SHA256); e != nil {
		return e
	}
	files, e := p.acquireCandidate()
	if e != nil {
		return e
	}
	// Build the signer inside --out so a rerun can reuse it by digest.
	toolDir := filepath.Join(o.Out, releaseToolDir)
	tool, prefix, record, reused := "", []string(nil), map[string]any(nil), false
	if o.ReleaseTool == "" && o.Resume {
		tool, prefix, record, reused = reuseReleaseTool(ctx, toolDir, p.manifest.SourceRevision, nil)
	}
	if !reused {
		buildDir := toolDir
		if o.ReleaseTool == "" {
			if e = os.MkdirAll(toolDir, 0755); e != nil {
				return e
			}
			// A fresh build directory per attempt: an interrupted earlier
			// run may have left its source worktree behind, and git refuses
			// to add a worktree at an existing path.
			if buildDir, e = os.MkdirTemp(toolDir, "build-"); e != nil {
				return e
			}
		}
		if tool, prefix, record, e = BuildReleaseTool(ctx, root, buildDir, p.manifest.SourceRevision, o.ReleaseTool, nil); e != nil {
			return e
		}
		if o.ReleaseTool == "" {
			if e = recordReleaseTool(toolDir, p.manifest.SourceRevision, prefix, record); e != nil {
				return e
			}
		}
	} else {
		p.step("reusing release tool sha256=" + record["sha256"].(string))
	}
	p.releasePrefix = prefix
	tools["ts_release"] = record
	release := func(capture bool, args ...string) (string, error) {
		return p.run(capture, append(append([]string{tool}, prefix...), args...)...)
	}
	image := filepath.Join(o.Out, "image", imageAssets[0])
	kernel := filepath.Join(o.Out, "image", imageAssets[1])
	region := p.manifest.Inputs.Manifest.Region
	if region != "GRU" {
		return errors.New("unsupported image region")
	}
	trust := []string{"--delegation", o.Delegation, "--root-key", o.RootKey, "--environment", o.Environment}
	delegationDigest, e := fileHash(o.Delegation)
	if e != nil {
		return e
	}
	rootDigest, e := fileHash(o.RootKey)
	if e != nil {
		return e
	}
	trustRecord := map[string]any{"delegation_sha256": delegationDigest, "root_key_sha256": rootDigest}
	p.receipt["trust"] = trustRecord
	candidate, ok := p.receipt["candidate"].(map[string]any)
	if !ok {
		return errors.New("invalid candidate metadata")
	}

	return e
}
receiptDigest, e := fileHash(files.receipt)
if e != nil {
	return e
}
candidate["binary_receipt_sha256"] = receiptDigest
p.step("signed binary receipt verified")
evidenceDir := o.ProductionEvidenceDir
if evidenceDir == "" {
	evidenceDir = filepath.Join(filepath.Dir(files.qualification), "image-production")
	if _, e = p.run(false, "bash", filepath.Join(root, "scripts/ci/fetch-image-production-evidence.sh"), p.manifest.Candidate.Tag,
		p.manifest.Image.SHA256, region, "arm64", evidenceDir); e != nil {
		return fmt.Errorf("acquire final image production qualification: %w", e)
	}
}
if _, e = release(false, "verify-image-production", "--image-file", image, "--qualification", files.qualification,
	"--root-key", o.RootKey, "--cell", region, "--environment", o.Environment, "--arch", "arm64",
	"--production-evidence-dir", evidenceDir); e != nil {
	return fmt.Errorf("final image production qualification: %w", e)
}
p.step("independent final image production qualification verified")
display := o.DisplayName
if display == "" {
	display = fmt.Sprintf("terrascale-%s-arm64-%s-%s", strings.ToLower(region), p.manifest.SourceRevision[:12], p.manifest.Image.SHA256[:12])
}
imageOCID := ""
if o.DryRun {
	imageOCID = "ocid1.image.oc1.sa-saopaulo-1.dryrun" + p.manifest.Image.SHA256[:32]
	p.receipt["oci_import"] = map[string]any{"skipped": "dry run", "display_name": display}
	p.step(fmt.Sprintf("dry run: would import %s as %s", image, display))
} else {
	importRecord := filepath.Join(o.Out, "oci-import.json")
	importer := o.Importer
	if importer == nil {
		importer = Services{}.importer()
	}
	var previous map[string]any
	if o.Resume && readJSON(importRecord, &previous) == nil && reusableImport(previous, p.manifest.Image.SHA256,
		o.CompartmentID, o.Namespace, o.Bucket, display) {
		p.step("reusing completed OCI import")
	} else if e = imageimport.RunImporters(ctx, []string{"--qcow2", image, "--sha256", p.manifest.Image.SHA256, "--region", catalog.OCIRegion(catalog.Bootstrap), "--compartment-id", o.CompartmentID, "--namespace", o.Namespace, "--bucket", o.Bucket, "--display-name", display, "--out", importRecord}, out, importer); e != nil {
		return e
	}
	var imported map[string]any
	if e = readJSON(importRecord, &imported); e != nil {
		return e
	}
	if imported["qcow2_sha256"] != p.manifest.Image.SHA256 {
		return errors.New("OCI import record differs from image")
	}
	imageOCID, _ = imported["image_id"].(string)
	if imageOCID == "" {
		return errors.New("OCI import record has no image identity")
	}
	p.receipt["oci_import"] = imported
	p.step("imported image_ocid=" + imageOCID)
}

func Execute(ctx context.Context, dir string, env []string, command ...string) (string, error) {
	if len(command) == 0 {
		return "", errors.New("empty command")
	}
	cmd := exec.CommandContext(ctx, command[0], command[1:]...)
	cmd.Dir = dir
	if env != nil {
		cmd.Env = env
	}
	cmd.WaitDelay = 2 * time.Second
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	var output, stderr bytes.Buffer
	cmd.Stdout = &output
	cmd.Stderr = &stderr
	if e := cmd.Run(); e != nil {
		action := strings.Join(command[:min(2, len(command))], " ")
		return "", fmt.Errorf("%s failed: %s: %w", action, strings.TrimSpace(stderr.String()+output.String()), e)
	}
	return strings.TrimSpace(output.String()), nil
}

func SHA256(path string) (string, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", e
	}
	defer f.Close()
	h := sha256.New()
	if _, e = io.Copy(h, f); e != nil {
		return "", e
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}
